static int g_board=0,g_model=0,g_sequence=0,g_stage=0,g_budget=0;static FILE*g_trace=nullptr;static BYTE*g_hooks[4]={},g_original[4]={},*g_return=nullptr,g_returnOriginal=0;static float*g_points=nullptr;static int*g_count=nullptr;static bool g_step=false;
