static void InstallFitTrace(){if(g_hooks[0])return;g_trace=fopen("candidate-trace.jsonl","wb");auto core=GetModuleHandleA("MVD_Algorithm.dll");if(!g_trace||!core)return;size_t addresses[]={0x8b5330,0x8b6c80,0x8b6f30,0x8bb3a0};for(int i=0;i<4;i++){g_hooks[i]=(BYTE*)core+addresses[i];g_original[i]=*g_hooks[i];}AddVectoredExceptionHandler(1,TraceCandidate);for(int i=0;i<4;i++)Patch(g_hooks[i],0xcc);}




